import type {
	ExerciseTemplate,
	GetV1ExerciseTemplates200,
} from "@hevy-mcp/hevy-client/types";
import type { HevyClient, HevyRequestOptions } from "@hevy-mcp/hevy-client";
import { AsyncTtlCache } from "./cache.js";
import type { CacheObservationMetadata, CacheObserver } from "./cache.js";
import { fetchAllPages } from "./pagination.js";
import { bucketCount } from "./result-telemetry.js";

const EXERCISE_TEMPLATE_CATALOG_CACHE_KEY = "exercise-template-catalog";
const EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS = 5 * 60 * 1000;
const EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE = 1;

export type ExerciseTemplateCatalogRefreshReason =
	| "explicit-refresh"
	| "initial-load"
	| "ttl-expired";

export interface ExerciseTemplateCatalogOptions {
	refresh?: boolean;
	execution?: HevyRequestOptions;
	onRefreshed?: (
		catalog: ExerciseTemplate[],
		reason: ExerciseTemplateCatalogRefreshReason,
	) => void;
}

export interface ExerciseTemplateCatalog {
	get(options?: ExerciseTemplateCatalogOptions): Promise<ExerciseTemplate[]>;
	reset(): void;
}

export function createExerciseTemplateCatalog(
	hevyClient: Pick<HevyClient, "getExerciseTemplates">,
	cacheObserver?: CacheObserver,
): ExerciseTemplateCatalog {
	const cache = new AsyncTtlCache<string, ExerciseTemplate[]>({
		ttlMs: EXERCISE_TEMPLATE_CATALOG_CACHE_TTL_MS,
		maxSize: EXERCISE_TEMPLATE_CATALOG_CACHE_MAX_SIZE,
		observer: cacheObserver,
	});

	return {
		get(options = {}) {
			const reason = options.refresh
				? "explicit-refresh"
				: cache.size === 0
					? "initial-load"
					: "ttl-expired";
			let observationMetadata: CacheObservationMetadata | undefined;
			let pagesLoaded = 0;
			return cache.getOrFetch(
				EXERCISE_TEMPLATE_CATALOG_CACHE_KEY,
				async () => {
					const catalog = await fetchAllPages<ExerciseTemplate>(
						async (page, pageSize) => {
							pagesLoaded = page;
							const data: GetV1ExerciseTemplates200 =
								await hevyClient.getExerciseTemplates(
									{
										page,
										pageSize,
									},
									options.execution,
								);
							return {
								items: data?.exercise_templates ?? [],
								pageCount: data?.page_count,
							};
						},
						100,
					);
					observationMetadata = {
						refreshReason: reason,
						pageCountBucket: bucketCount(pagesLoaded),
						itemCountBucket: bucketCount(catalog.length),
					};
					options.onRefreshed?.(catalog, reason);
					return catalog;
				},
				{
					refresh: options.refresh,
					shareInFlight: options.execution === undefined,
					signal: options.execution?.signal,
					deadline: options.execution?.deadline,
					getObservationMetadata: () => observationMetadata,
				},
			);
		},
		reset() {
			cache.clear();
		},
	};
}

import { McpServer } from "@modelcontextprotocol/server";
import type { HevyClient, HevyClientLogEvent } from "@hevy-mcp/hevy-client";
import { registerWorkoutPrompts } from "./prompts/workouts.js";
import { registerHevyResources } from "./resources/hevy.js";
import {
	SERVER_INSTRUCTIONS,
	SERVER_NAME,
	SERVER_VERSION,
} from "./server-metadata.js";
import { registerHevyTools } from "./tools/register.js";
import { createToolRuntime } from "./tools/tool-runtime.js";
import { createExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";
import { createMcpClientLogger } from "./utils/mcp-client-logger.js";
import type { CacheObserver } from "./utils/cache.js";
import type { ToolObserver } from "./observation.js";
export interface HevyClientFactoryContext {
	readonly onLog: (event: HevyClientLogEvent) => void;
}

export interface CreateHevyMcpServerOptions {
	readonly createClient: (context: HevyClientFactoryContext) => HevyClient;
	readonly observer?: ToolObserver;
	readonly cacheObserver?: CacheObserver;
	readonly decorateServer?: (server: McpServer) => McpServer;
	readonly onToolsRegistered?: (count: number) => void;
	/** One absolute budget for each incoming MCP invocation. */
	readonly executionTimeoutMs?: number;
	/** Absolute deadline shared by validation and every tool call in one invocation. */
	readonly executionDeadline?: number;
	readonly lifecycleSignal?: AbortSignal;
}

function createCountingServer(server: McpServer) {
	let count = 0;
	const countingServer = new Proxy(server, {
		get(target, property, receiver) {
			if (property === "registerTool") {
				const registerTool = target.registerTool.bind(target);
				return (...args: unknown[]) => {
					const result = Reflect.apply(registerTool, target, args);
					count += 1;
					return result;
				};
			}
			return Reflect.get(target, property, receiver);
		},
	});
	return { server: countingServer, getCount: () => count };
}

export function createHevyMcpServer(
	options: CreateHevyMcpServerOptions,
): McpServer {
	const baseServer = new McpServer(
		{ name: SERVER_NAME, version: SERVER_VERSION },
		{ capabilities: { logging: {} }, instructions: SERVER_INSTRUCTIONS },
	);
	const server = options.decorateServer?.(baseServer) ?? baseServer;
	const mcpLogger = createMcpClientLogger(server);
	const client = options.createClient({ onLog: (event) => mcpLogger(event) });
	const runtime = createToolRuntime({
		client,
		catalog: createExerciseTemplateCatalog(client, options.cacheObserver),
		logger: mcpLogger,
		observer: options.observer,
		executionTimeoutMs: options.executionTimeoutMs,
		executionDeadline: options.executionDeadline,
		lifecycleSignal: options.lifecycleSignal,
	});
	const counting = createCountingServer(server);
	registerHevyTools(counting.server, runtime);
	options.onToolsRegistered?.(counting.getCount());
	registerWorkoutPrompts(server, options.observer);
	registerHevyResources(server, runtime);
	return server;
}

import { describe, expect, it, vi } from "vitest";
import { Effect } from "effect";

import {
	createRoutinesGetOperation,
	createRoutinesListOperation,
} from "./routines.js";
import {
	createWorkoutsGetOperation,
	createWorkoutsListOperation,
} from "./workouts.js";

function assertCollapsedExecute(source: string): void {
	expect(source.match(/Effect\.runPromise/g)).toHaveLength(1);
	expect(source).not.toMatch(/Effect\.(tryPromise|promise)/);
	expect(source).toContain("Effect.catchIf");
}

describe("operations Effect collapse", () => {
	it("collapses workouts.get onto one Effect boundary", () => {
		const operation = createWorkoutsGetOperation({
			getWorkout: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses workouts.list onto one Effect boundary", () => {
		const operation = createWorkoutsListOperation({
			getWorkouts: () => Effect.succeed({ workouts: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.get onto one Effect boundary", () => {
		const operation = createRoutinesGetOperation({
			getRoutineById: () => Effect.succeed({}),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("collapses routines.list onto one Effect boundary", () => {
		const operation = createRoutinesListOperation({
			getRoutines: () => Effect.succeed({ routines: [] }),
		});

		assertCollapsedExecute(operation.execute.toString());
	});

	it("passes an Effect-capable read seam directly into execute", async () => {
		const getWorkout = vi.fn(() => Effect.succeed({ id: "workout-1" }));
		const operation = createWorkoutsGetOperation({ getWorkout });

		await expect(
			operation.execute({ workoutId: "workout-1" }),
		).resolves.toEqual({
			workout: { id: "workout-1" },
		});

		const seamResult = getWorkout.mock.results[0]?.value;
		expect(seamResult).toBeDefined();
		await expect(Effect.runPromise(seamResult)).resolves.toEqual({
			id: "workout-1",
		});
	});
});

import type { HevyClient, HevyExecutionOptions } from "@hevy-mcp/hevy-client";
import { z } from "zod";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	getV1BodyMeasurementsQueryParamsSchema,
	getV1RoutinesQueryParamsSchema,
} from "@hevy-mcp/hevy-client/schemas";
import {
	buildMeasurementPayload,
	buildRoutinePayload,
	createBodyMeasurementInputSchema,
	createRoutineInputSchema,
	existingBodyMeasurementSchema,
	exerciseTemplateInputSchema,
	mergeMeasurementPayload,
	routineFolderInputSchema,
	updateBodyMeasurementInputSchema,
	updateRoutineInputSchema,
	replaceWorkoutInputSchema,
	workoutInputSchema,
} from "@hevy-mcp/core/mutations";
import {
	parseExerciseHistoryId,
	parseExerciseHistoryOptions,
	parseExerciseId,
	parseMeasurementDate,
	parseSearchMaxPages,
	parsePagination,
	parseRoutineId,
	parseSearchQuery,
	parseWeeks,
	parseWorkoutEventsOptions,
	parseWorkoutId,
	requireMutationConfirmation,
	UsageError,
	type CliArgs,
} from "../arguments.js";
import { ApiResponseError } from "../errors.js";
import {
	loadMutationInput,
	readDataSource as defaultDataSourceReader,
	type DataSourceReader,
} from "../input.js";
import {
	pageEnvelope,
	type ApiObject,
	type ApiValue,
} from "../output/contracts.js";

type Body = ApiObject;
function body(value: ApiValue): Body {
	const parsed = z.object({}).passthrough().safeParse(value);
	if (!parsed.success) return {};
	const result: Body = {};
	for (const [key, item] of Object.entries(parsed.data)) {
		const parsedItem = z
			.union([
				z.string(),
				z.number(),
				z.boolean(),
				z.null(),
				z.array(z.unknown()),
			])
			.safeParse(item);
		if (parsedItem.success) result[key] = parsedItem.data as ApiValue;
	}
	return result;
}
function array(value: ApiValue): ApiValue[] {
	return Array.isArray(value) ? value : [];
}
function text(value: ApiValue): string {
	return z.string().safeParse(value).data ?? "";
}
function list(data: Body, source: string, output: string, page: number): Body {
	const count = z.number().safeParse(data.page_count).data;
	if (
		count === undefined ||
		!Number.isInteger(count) ||
		count < 0 ||
		(data.page !== undefined && data.page !== page)
	)
		throw new ApiResponseError("The API returned invalid pagination metadata");
	if (count > 0 && page > count)
		throw new UsageError("Requested page exceeds the API page count");
	return pageEnvelope(
		data,
		output,
		Array.isArray(data[source]) ? data[source] : [],
	);
}
const createBodyMeasurementDataSchema = createBodyMeasurementInputSchema.refine(
	(fields) =>
		Object.entries(fields).some(
			([key, value]) => key !== "date" && z.number().safeParse(value).success,
		),
	"Include at least one numeric measurement field",
);
const updateBodyMeasurementDataSchema = updateBodyMeasurementInputSchema.refine(
	(fields) => Object.keys(fields).some((key) => key !== "date"),
	"Include at least one measurement field",
);

function mutationData(args: CliArgs): string {
	const value = args.options.data;
	const parsed = z.string().safeParse(value);
	if (!parsed.success) throw new UsageError("--data is required");
	return parsed.data;
}

type CommandContext = {
	args: CliArgs;
	client: HevyClient;
	now: () => Date;
	readDataSource: DataSourceReader;
	operations: HevyOperations;
	execution?: HevyExecutionOptions;
};

type CommandResult = Promise<unknown>;

function executeRead<T>(
	execution: HevyExecutionOptions | undefined,
	request: () => Promise<T>,
	requestWithExecution: (execution: HevyExecutionOptions) => Promise<T>,
): Promise<T> {
	return execution === undefined ? request() : requestWithExecution(execution);
}

