async function collectSummaryWorkouts(
	client: HevyClient,
	from: Date,
	to: Date,
	execution?: HevyExecutionOptions,
) {
	let pageNumber = 1;
	let pageCount = 1;
	let pagesScanned = 0;
	const workouts: Body[] = [];
	while (pageNumber <= pageCount) {
		const params = { page: pageNumber, pageSize: 10 };
		const result = body(
			await executeRead(
				execution,
				() => client.getWorkouts(params),
				(options) => client.getWorkouts(params, options),
			),
		);
		pageCount = result.page_count as number;
		if (
			!Number.isInteger(pageCount) ||
			pageCount < 0 ||
			(result.page !== undefined && result.page !== pageNumber) ||
			(pageCount > 0 && pageCount < pageNumber)
		)
			throw new ApiResponseError(
				"The API returned invalid pagination metadata",
			);
		pagesScanned += 1;
		if (pageCount === 0) break;
		const items = Array.isArray(result.workouts)
			? result.workouts.map(body)
			: [];
		for (const workout of items) {
			const timestamp = Date.parse(text(workout.start_time));
			if (Number.isNaN(timestamp))
				throw new ApiResponseError(
					"The API returned a workout with an invalid timestamp",
				);
			if (timestamp >= from.getTime() && timestamp <= to.getTime())
				workouts.push(workout);
		}
		pageNumber += 1;
	}
	return { workouts, pageNumber, pageCount, pagesScanned };
}

function summarizeWorkouts(workouts: readonly Body[]) {
	let exerciseCount = 0;
	let setCount = 0;
	let totalVolumeKg = 0;
	let totalDurationSeconds = 0;
	for (const workout of workouts) {
		const start = Date.parse(text(workout.start_time));
		const end = Date.parse(text(workout.end_time));
		if (!Number.isNaN(start) && !Number.isNaN(end))
			totalDurationSeconds += Math.max(0, (end - start) / 1000);
		const exercises = array(workout.exercises);
		exerciseCount += exercises.length;
		for (const exercise of exercises)
			for (const set of array(body(exercise).sets)) {
				setCount += 1;
				const item = body(set);
				const weight = z.number().safeParse(item.weight_kg).data;
				const reps = z.number().safeParse(item.reps).data;
				if (weight !== undefined && reps !== undefined)
					totalVolumeKg += weight * reps;
			}
	}
	return { exerciseCount, setCount, totalVolumeKg, totalDurationSeconds };
}

async function executeSummary({
	args,
	client,
	now,
	execution,
}: CommandContext) {
	const weeks = parseWeeks(args);
	const to = now();
	const from = new Date(to.getTime() - weeks * 7 * 24 * 60 * 60 * 1000);
	const collection = await collectSummaryWorkouts(client, from, to, execution);
	const totals = summarizeWorkouts(collection.workouts);
	return {
		weeks,
		start_date: from.toISOString(),
		end_date: to.toISOString(),
		workout_count: collection.workouts.length,
		total_duration_seconds: totals.totalDurationSeconds,
		exercise_count: totals.exerciseCount,
		set_count: totals.setCount,
		total_volume_kg: totals.totalVolumeKg,
		pages_scanned: collection.pagesScanned,
		complete: collection.pageNumber > collection.pageCount,
	};
}

export async function execute(
	args: CliArgs,
	client: HevyClient,
	now = () => new Date(),
	readDataSource: DataSourceReader = defaultDataSourceReader,
	operations: HevyOperations = createOperations(client),
	execution?: HevyExecutionOptions,
): Promise<unknown> {
	const context: CommandContext = {
		args,
		client,
		now,
		readDataSource,
		operations,
		execution,
	};
	if (args.command === "user" && !args.subcommand)
		return {
			user: await executeRead(
				context.execution,
				() => client.getUserInfo(),
				(options) => client.getUserInfo(options),
			),
		};
	if (args.command === "workouts") return executeWorkouts(context);
	if (args.command === "routines") return executeRoutines(context);
	if (args.command === "exercises") return executeExercises(context);
	if (args.command === "measurements") return executeMeasurements(context);
	if (args.command === "folders" && args.subcommand === "create")
		return executeFolderCreate(context);
	if (args.command === "summary") return executeSummary(context);
	throw new UsageError("Unknown command; run hevy --help");
}

import { describe, expect, it } from "vitest";
import {
	findImportViolations,
	findRetiredRootSourceFiles,
	inspectFileWithCompiler,
	packageRules,
} from "../../scripts/check-package-boundaries.mjs";

const coreRule = packageRules.get("packages/core");
if (!coreRule) throw new Error("core boundary rule is missing");
const workerRule = packageRules.get("packages/worker");
if (!workerRule) throw new Error("worker boundary rule is missing");

describe("package boundary AST checker", () => {
	it("uses the TypeScript compiler AST for workspace files", () => {
		const result = inspectFileWithCompiler(
			"tests/fixtures/package-boundary-syntax.cts",
		);
		if (!result) throw new Error("Compiler inspection returned no result");
		expect(result.usedCompilerApi).toBe(true);
		expect(result.edges.map(({ specifier }) => specifier)).toEqual(
			expect.arrayContaining([
				"@hevy-mcp/hevy-client",
				"@hevy-mcp/hevy-client/types",
				"@hevy-mcp/hevy-client/schemas",
			]),
		);
		expect(result.edges).toHaveLength(5);
		expect(result.edges.map(({ kind }) => kind)).toEqual(
			expect.arrayContaining(["import-equals", "import()", "require"]),
		);
		expect(result.nonLiteralCalls).toEqual([]);
	});

	it("rejects escaped relative imports and non-literal loading", () => {
		const failures = findImportViolations({
			source: `import "../../node/src/index.ts"; import(` + "name" + `);`,
			file: "/repo/packages/core/src/file.ts",
			fileName: "file.ts",
			relativePackage: "packages/core",
			packageRoot: "/repo/packages/core",
			rule: coreRule,
		});
		expect(failures).toEqual([
			"packages/core: non-literal dynamic import/require in /repo/packages/core/src/file.ts",
			"packages/core: relative import escapes package: ../../node/src/index.ts",
		]);
	});

	it("rejects runtime adapters and unexported internal subpaths", () => {
		const failures = findImportViolations({
			source: `import "@hevy-mcp/hevy-client/generated/client/api"; import "node:fs"; import "cloudflare:workers";`,
			file: "/repo/packages/core/src/file.ts",
			fileName: "file.ts",
			relativePackage: "packages/core",
			packageRoot: "/repo/packages/core",
			rule: coreRule,
		});
		expect(failures).toEqual([
			"packages/core: forbidden internal import: @hevy-mcp/hevy-client/generated/client/api",
			"packages/core: forbidden Node builtin import: node:fs",
			"packages/core: forbidden runtime import: cloudflare:workers",
		]);
	});

	it("rejects the public Node package from runtime-neutral packages", () => {
		const failures = findImportViolations({
			source: `import "hevy-mcp";`,
			file: "/repo/packages/core/src/file.ts",
			fileName: "file.ts",
			relativePackage: "packages/core",
			packageRoot: "/repo/packages/core",
			rule: coreRule,
		});
		expect(failures).toEqual([
			"packages/core: forbidden internal import: hevy-mcp",
		]);
	});

	it("derives Worker runtime restrictions from topology", () => {
		const source = [
			'import "node:fs";',
			'import "@sentry/node";',
			'import "@opentelemetry/sdk-trace-node";',
		].join(" ");
		const failures = findImportViolations({
			source,
			file: "/repo/packages/worker/src/file.ts",
			fileName: "file.ts",
			relativePackage: "packages/worker",
			packageRoot: "/repo/packages/worker",
			rule: workerRule,
		});
		expect(failures).toEqual([
			"packages/worker: forbidden Node builtin import: node:fs",
			"packages/worker: forbidden runtime import: @sentry/node",
			"packages/worker: forbidden runtime import: @opentelemetry/sdk-trace-node",
		]);
	});

	it("rejects implementation files reintroduced under the root source tree", () => {
		expect(
			findRetiredRootSourceFiles(
				[
					"/repo/src/index.ts",
					"/repo/src/shared-server.ts",
					"/repo/src/tools/workouts.ts",
					"/repo/src/generated/client.ts",
				],
				"/repo",
			),
		).toEqual([
			"src/index.ts",
			"src/shared-server.ts",
			"src/tools/workouts.ts",
			"src/generated/client.ts",
		]);
	});
});

import { Layer } from "effect";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import {
	ExerciseTemplateCatalogService,
	HevyClientService,
	HevyOperationsService,
	ToolExecutionContextService,
	ToolObserverService,
} from "./effect-services.js";
import type { ToolExecutionContext } from "./execution.js";
import type { ToolObserver } from "./observation.js";
import type { ExerciseTemplateCatalog } from "./utils/exercise-template-catalog.js";

export interface CoreServiceLayerOptions {
	readonly client: HevyClient;
	readonly catalog: ExerciseTemplateCatalog;
	readonly execution: ToolExecutionContext;
	readonly operations?: HevyOperations;
}

export type CoreServiceIdentifiers =
	| HevyClientService
	| HevyOperationsService
	| ExerciseTemplateCatalogService
	| ToolExecutionContextService;

export type CoreServiceLayer = Layer.Layer<CoreServiceIdentifiers>;

/**
 * Build the runtime-neutral dependency graph for an Effect program.
 *
 * The returned layer is intentionally request-local. ToolRuntime builds it
 * for each runtime or execution scope rather than installing a process-wide
 * Effect runtime.
 */
export function createCoreServiceLayer({
	client,
	catalog,
	execution,
	operations = createOperations(client),
}: CoreServiceLayerOptions): CoreServiceLayer {
	return Layer.mergeAll(
		Layer.succeed(HevyClientService, client),
		Layer.succeed(HevyOperationsService, operations),
		Layer.succeed(ExerciseTemplateCatalogService, catalog),
		Layer.succeed(ToolExecutionContextService, execution),
	);
}

export function createToolObserverLayer(
	observer: ToolObserver,
): Layer.Layer<ToolObserverService> {
	return Layer.succeed(ToolObserverService, observer);
}

import { Context } from "effect";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import type { HevyOperations } from "@hevy-mcp/operations";
import type { ToolExecutionContext } from "./execution.js";
import type { ToolObserver } from "./observation.js";
